function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.gear}"></path></svg>`;}
const fmt=n=>Number(n).toLocaleString();
let index,rawCatalog,manuals=[],viewer,viewerPromise=null,renderToken=0;
let state={system:null,group:null,part:null,view:'vehicle',detail:false,filter:'all',partQuery:'',diagram:0,diagramZoom:1};
let saved=readSaved(),toastTimer,searchTimer,searchLimit=24;
function readSaved(){try{const list=JSON.parse(localStorage.getItem('accord-catalog-plan')||'[]');return Array.isArray(list)?list.filter(v=>v&&typeof v.id==='string'):[];}catch{return[];}}
function saveStore(){try{localStorage.setItem('accord-catalog-plan',JSON.stringify(saved));}catch{toast('Saved for this session. Browser storage is unavailable.');}$('plan-count').textContent=saved.length;}
function toast(s){clearTimeout(toastTimer);$('toast').textContent=s;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3000);}
function dialog(id){$(id).showModal();document.body.style.overflow='hidden';}
function closeDialogs(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());}
function groupURL(id,part,view,detail=false){const q=new URLSearchParams();if(part)q.set('part',part);if(view)q.set('view',view);if(detail)q.set('detail','1');return '#assembly/'+encodeURIComponent(id)+(q.size?'?'+q:'');}
function go(href){closeDialogs();$('workspace').classList.remove('systems-open');if(location.hash===href)route();else location.hash=href;}
function openGroup(id,number,view){const g=index?.groupMap.get(id);if(!g)return;go(groupURL(id,number,view));}
function chooseSystem(id){go(id?'#system/'+id:'#car');}
function route(){if(!index)return;const [path,params]=location.hash.slice(1).split('?');const q=new URLSearchParams(params||'');const previous=state.group?.id;const tokens=(path||'car').split('/');let g=null,system=null,detail=q.get('detail')==='1';
 if(tokens[0]==='assembly'){g=index.groupMap.get(decodeURIComponent(tokens[1]||''));system=g?.systemId||null;}
 else if(tokens[0]==='system'){system=systemById[tokens[1]]?tokens[1]:null;}
 else{const old={ignition:'ignition',starting:'ignition',brakes:'brakes',sensors:'sensors',catalog:null,powertrain:'engine',fuel:'fuel',body:'body',electrical:'electrical'};system=old[tokens[0]]||null;}
 const model=modelFor(g);const defaultView=g?(model==='intake'||model==='alternator'?'3d':'diagram'):'vehicle';let view=q.get('view')||defaultView;const valid=g?(detail?['photo','diagram',...(model?['3d']:[])]:['photo','diagram',...(model?['3d']:[])]):['vehicle','3d'];if(!valid.includes(view))view=defaultView;
 const part=g?(g.parts.find(p=>p.number===q.get('part'))||primaryPart(g)):null;
 state={...state,system,group:g,part,view,detail:g&&detail,filter:previous===g?.id?state.filter:'all',partQuery:previous===g?.id?state.partQuery:'',diagram:Math.max(0,g?.diagrams.findIndex(d=>d.hotspots.some(h=>h.code===part?.ref))||0),diagramZoom:1};render();
 if(tokens[0]==='resources')showResources();
}
function setView(view){state.view=view;state.diagramZoom=1;replaceHash();renderVisual();renderInspector();}
function replaceHash(){const href=state.group?groupURL(state.group.id,state.part?.number,state.view,state.detail):(state.system?'#system/'+state.system:'#car')+(state.view==='3d'?'?view=3d':'');history.replaceState(null,'',href);}
function render(){renderNav();renderBreadcrumbs();renderVisual();renderInspector();renderInside();$('back-button').hidden=!state.system&&!state.group;}
function renderNav(){$('system-nav').innerHTML=`<button class="system-item ${!state.system?'active':''}" data-system="" ${!state.system?'aria-current="page"':''}>${icon('car')}<span>Whole vehicle</span></button>`+SYSTEMS.map(s=>{const n=groupsFor(index,s.id).length+index.missing.filter(g=>g.systemId===s.id).length;return `<button class="system-item ${state.system===s.id?'active':''}" data-system="${s.id}" ${state.system===s.id?'aria-current="page"':''}>${icon(s.icon)}<span>${esc(s.name)}</span><small class="system-count">${n}</small></button>`;}).join('');}
function renderBreadcrumbs(){const s=systemById[state.system],g=state.group;const pieces=['<a href="#car">My Accord</a>'];if(s)pieces.push(`<a href="#system/${s.id}">${esc(s.name)}</a>`);if(g)pieces.push(state.detail?`<a href="${groupURL(g.id,null,state.view==='photo'?null:state.view)}">${esc(cleanName(g.name))}</a>`:`<span aria-current="page">${esc(cleanName(g.name))}</span>`);if(state.detail)pieces.push(`<span aria-current="page">${esc(cleanName(state.part?.name))}</span>`);$('breadcrumbs').innerHTML=pieces.join('<i aria-hidden="true">/</i>');}
function mainFeature(g){return featured.find(f=>f.group===g?.id&&!f.sensor)||null;}
function cropStyle(f){const w=f.sensor?706:977,h=f.sensor?954:1610,c=f.crop;return `background-image:url('./assets/${f.sensor?'sensor':'reference'}-atlas.png');background-size:${w/c.w*100}% auto;background-position:${c.x/(w-c.w)*100}% ${c.y/(h-c.h)*100}%;aspect-ratio:${c.w}/${c.h};`;}
function imageHTML(url,alt,extra=''){return url?`<img src="${esc(url)}" alt="${esc(alt)}" ${extra} decoding="async">`:'';}
function renderVisual(){const token=++renderToken;const g=state.group,s=systemById[state.system];viewer?.setActive(false);$('webgl-mount').hidden=true;$('model-labels').hidden=true;$('model-controls').hidden=true;$('visual-content').hidden=false;$('visual-content').innerHTML='';$('stage-tools').innerHTML='';
 $('stage-kicker').textContent=g?(state.detail?'INDIVIDUAL COMPONENT · CALLOUT '+(state.part?.ref||'—'):'ASSEMBLY EXPLORER'):s?s.zone:'YOUR 2012 ACCORD';
 $('stage-title').textContent=state.detail?cleanName(state.part?.name):g?cleanName(g.name):s?s.name:'Explore from the car';
 const views=g?[['photo',state.detail?'Part photo':'Part view'],['diagram','OEM diagram'],...(modelFor(g)?[['3d','3D study']]:[])]:[['vehicle','Vehicle'],['3d','3D systems']];
 $('view-tabs').innerHTML=views.map(([id,title])=>`<button data-view="${id}" class="${state.view===id?'active':''}" aria-pressed="${state.view===id}">${title}</button>`).join('');
 if(state.view==='3d'){
  $('visual-content').innerHTML='<p class="empty-state">Opening 3D view…</p>';$('stage-caption').innerHTML=g?'Illustrative 3D study. Use the OEM diagram for exact mounting locations.':'System positions are an illustrative orientation map of the car.';
  const kind=g?modelFor(g):'vehicle';loadViewer().then(v=>{if(token!==renderToken||state.view!=='3d')return;$('visual-content').hidden=true;$('webgl-mount').hidden=false;$('model-labels').hidden=false;$('model-controls').hidden=false;v.load(kind,g);v.select(g?state.part?.ref:state.system);v.setLabels($('labels-toggle').getAttribute('aria-pressed')==='true');$('explode-slider').disabled=!!v.single;$('explode-slider').value=0;v.setExplode(0);$('isolate-toggle').setAttribute('aria-pressed','false');$('isolate-toggle').disabled=!g&&!state.system;v.isolate(false);v.resize();}).catch(()=>{if(token===renderToken)show3dFailure();});
 }else if(!g){
  const focus=state.system;const major=['engine','brakes','body','electrical','interior','cooling'];$('visual-content').innerHTML='<div class="car-art" aria-hidden="true"></div>'+SYSTEMS.map(s=>`<button class="car-point ${focus===s.id?'active':focus||!major.includes(s.id)?'secondary':''}" style="left:${s.point[0]*100}%;top:${s.point[1]*100}%" data-system="${s.id}" aria-label="Explore ${esc(s.name)}"><i aria-hidden="true"></i><span>${esc(s.name)}</span></button>`).join('')+'<span class="car-label">ACCORD LX · 2.4L</span>';$('stage-caption').textContent='Choose a system on the car or in the system menu. Markers identify areas of interest.';
 }else if(state.view==='diagram')renderDiagram();
 else{const f=!state.detail&&mainFeature(g);const p=state.detail?state.part:primaryPart(g);if(f){$('visual-content').innerHTML=`<div class="assembly-art-frame"><div class="assembly-art" style="${cropStyle(f)}" role="img" aria-label="Illustration of ${esc(f.title)}"></div></div>`;$('stage-caption').innerHTML='Component-family artwork. Open the OEM diagram for the assembly breakdown.';}else if(p?.images?.length){$('visual-content').innerHTML=imageHTML(p.images[0],p.name,'class="assembly-image" data-image-kind="part"');$('stage-caption').innerHTML=`${esc(p.name)} · ${esc(p.number)} <a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Source photo ↗</a>`;}else{$('visual-content').innerHTML='<div class="image-unavailable">No separate photo is listed for this component.<button class="button" data-view="diagram">Show it in the OEM diagram</button></div>';$('stage-caption').textContent='The numbered diagram identifies the component in its parent assembly.';}}
}
async function loadViewer(){if(viewer)return viewer;if(!viewerPromise)viewerPromise=import('./studio-3d.js').then(({VehicleViewer})=>{viewer=new VehicleViewer($('webgl-mount'),$('model-labels'),data=>{if(data.system)chooseSystem(data.system);else if(data.ref)selectCallout(data.ref);},show3dFailure);return viewer;}).catch(e=>{viewerPromise=null;throw e;});return viewerPromise;}
function show3dFailure(){viewer?.setActive(false);$('webgl-mount').hidden=true;$('model-labels').hidden=true;$('model-controls').hidden=true;$('visual-content').hidden=false;$('visual-content').innerHTML=`<div class="image-unavailable">3D is unavailable in this browser.<button class="button" data-view="${state.group?'diagram':'vehicle'}">Continue with ${state.group?'the OEM diagram':'the vehicle map'}</button></div>`;}
function renderDiagram(){const g=state.group,d=g.diagrams[state.diagram];if(!d){$('visual-content').innerHTML=`<div class="image-unavailable">The source has no diagram for this assembly.<a class="button" href="${esc(g.url)}" target="_blank" rel="noopener noreferrer">Open source catalog ↗</a></div>`;return;}
 $('visual-content').innerHTML=`<div class="diagram-scroll"><div class="diagram-stage" style="width:${state.diagramZoom*100}%"><div class="diagram-canvas">${imageHTML(d.image,d.name+' numbered OEM assembly diagram','data-image-kind="diagram"')}${d.hotspots.map(h=>{const pos=['top','left','width','height'].map(k=>`${k}:${/^\d+(\.\d+)?%$/.test(h[k])?h[k]:'0%'}`).join(';');const p=g.parts.find(p=>p.ref===h.code);return `<button class="diagram-hotspot ${state.part?.ref===h.code?'active':''}" style="${pos}" data-callout="${esc(h.code)}" aria-label="Callout ${esc(h.code)}${p?' · '+esc(p.name):''}" title="${esc(h.code)}${p?' · '+esc(p.name):''}"></button>`;}).join('')}</div></div></div>`;
 $('stage-tools').innerHTML=`<div class="stage-tools">${g.diagrams.length>1?`<select class="diagram-selector" id="diagram-select" aria-label="Choose assembly diagram">${g.diagrams.map((d,i)=>`<option value="${i}" ${state.diagram===i?'selected':''}>${i+1}. ${esc(d.name)}</option>`).join('')}</select>`:''}<button data-diagram-zoom="out" aria-label="Zoom diagram out">−</button><button data-diagram-zoom="reset" aria-label="Reset diagram zoom">${state.diagramZoom}×</button><button data-diagram-zoom="in" aria-label="Zoom diagram in">+</button></div>`;
 $('stage-caption').innerHTML=`Choose a numbered callout to select its part. <a href="${esc(g.url)}" target="_blank" rel="noopener noreferrer">HondaPartsNow diagram ↗</a>`;
}
function renderInspector(){const g=state.group,s=systemById[state.system];if(g){$('inspector').innerHTML=`<div class="parts-heading"><h3>Inside this assembly</h3><span>${g.parts.length} entries</span></div><input class="part-filter" id="part-filter" type="search" placeholder="Find a part or callout…" aria-label="Filter parts in this assembly" value="${esc(state.partQuery)}"><div class="part-tabs" role="group" aria-label="Filter assembly parts">${[['all','All'],['components','Components'],['hardware','Hardware'],['seals','Seals']].map(([id,name])=>`<button data-part-filter="${id}" class="${state.filter===id?'active':''}" aria-pressed="${state.filter===id}">${name}</button>`).join('')}</div><div class="part-list" id="part-list"></div><div class="part-detail" id="part-detail"></div>`;renderRows();renderPartDetail();return;}
 if(s){const gs=groupsFor(index,s.id);const partCount=new Set(gs.flatMap(g=>g.parts.map(p=>p.number))).size;const intro=s.id==='sensors'?'Sensors appear here across systems; each opens in its own parent assembly.':s.description;const picks=pickGroups(s.id).slice(0,4);$('inspector').innerHTML=`<p class="eyebrow">SYSTEM OVERVIEW</p><h3>${esc(s.name)}</h3><p class="body-copy">${esc(intro)}</p><div class="mini-stat"><span>Assemblies</span><strong>${gs.length}</strong></div><div class="mini-stat"><span>OEM numbers</span><strong>${fmt(partCount)}</strong></div><div class="quick-list">${picks.map(g=>`<button class="quick-item" data-group="${g.id}"><span>${esc(cleanName(g.name))}</span><span>→</span></button>`).join('')}</div><p class="inspector-footnote">Open an assembly to see its components, seals, and mounting hardware together.</p><button class="text-button resources-inline">System guides &amp; references ↗</button>`;return;}
 $('inspector').innerHTML=`<p class="eyebrow">VEHICLE EXPLORER</p><h3>Start outside.<br>Understand inside.</h3><p class="body-copy">Open a system, inspect an assembly, then follow any part down to its hardware.</p><button class="button full" data-system="engine">Explore engine &amp; intake <span>→</span></button><div class="quick-list"><button class="quick-item" data-group="${INTAKE}" data-view-hint="3d">${icon('engine')}<span>Intake manifold</span><span>↗</span></button><button class="quick-item" data-group="engine--alternator_denso_l4" data-view-hint="3d">${icon('bolt')}<span>Alternator</span><span>↗</span></button></div><div class="mini-stat"><span>System views</span><strong>${SYSTEMS.length}</strong></div><div class="mini-stat"><span>Assemblies</span><strong>${index.groups.length}</strong></div><p class="inspector-footnote">OEM diagrams and service references stay connected to the part you’re exploring.</p>`;
}
function renderRows(){if(!$('part-list'))return;const list=state.group.parts.map((p,i)=>({p,i})).filter(({p})=>matches(p,state.partQuery)&&(state.filter==='all'||state.filter==='hardware'&&isHardware(p)||state.filter==='seals'&&isSeal(p)||state.filter==='components'&&!isHardware(p)&&!isSeal(p)));$('part-list').innerHTML=list.length?list.map(({p,i})=>`<button class="part-row ${p===state.part?'active':''}" data-row="${i}" aria-pressed="${p===state.part}"><span class="callout-number">${esc(p.ref||'—')}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.number)}</small></span></button>`).join(''):'<p class="empty-state">No matching parts in this filter.<button class="text-button" id="reset-part-filters">Show all parts</button></p>';}
function renderPartDetail(){const g=state.group,p=state.part;if(!p)return;const id=g.id+':'+p.number,added=saved.some(s=>s.id===id);const alternatives=g.parts.filter(v=>v.ref===p.ref).length;const extra=[...(p.extra||[]).map(e=>e.name&&e.desc?e.name+': '+e.desc:''),(p.note||'')].filter(Boolean).join(' · ');
 $('part-detail').innerHTML=`${p.images?.[0]?imageHTML(p.images[0],p.name,'class="selected-photo" data-image-kind="thumb"'):''}<p class="eyebrow">CALLOUT ${esc(p.ref||'—')}</p><h4>${esc(p.name)}</h4><span class="number">${esc(p.number)}</span>${extra?`<p>${esc(extra)}</p>`:''}${p.replacement?`<p>Replacement reference: ${esc(p.replacement)}</p>`:''}<p>${alternatives>1?alternatives+' catalog entries share this callout. ':''}Confirm VIN and applicable replacements before ordering.</p><div class="part-detail-actions"><button class="button" id="inspect-part">Inspect part ↗</button><button class="button secondary" id="save-part" aria-pressed="${added}">${added?'✓ Saved':'♡ Save'}</button><a class="text-button" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Price &amp; fitment ↗</a></div>`;
}
function selectRow(i){const p=state.group.parts[i];if(!p)return;state.part=p;const diagrams=state.group.diagrams;if(!diagrams[state.diagram]?.hotspots.some(h=>h.code===p.ref)){const d=diagrams.findIndex(d=>d.hotspots.some(h=>h.code===p.ref));if(d>=0){state.diagram=d;state.diagramZoom=1;if(state.view==='diagram')renderDiagram();}}replaceHash();renderRows();renderPartDetail();renderBreadcrumbs();document.querySelectorAll('[data-callout]').forEach(b=>b.classList.toggle('active',b.dataset.callout===p.ref));viewer?.select(p.ref);if(state.detail&&state.view==='photo')renderVisual();}
function selectCallout(ref){const i=state.group?.parts.findIndex(p=>p.ref===ref);if(i==null||i<0){toast('No separately listed service part for this callout.');return;}state.filter='all';state.partQuery='';state.part=state.group.parts[i];replaceHash();renderInspector();renderBreadcrumbs();document.querySelectorAll('[data-callout]').forEach(b=>b.classList.toggle('active',b.dataset.callout===ref));viewer?.select(ref);requestAnimationFrame(()=>{const list=$('part-list'),selected=list?.querySelector('.active');if(list&&selected)list.scrollTop=selected.offsetTop-list.offsetTop-25;});}
const preferred={engine:[INTAKE,'engine--cylinder_head_l4','engine--camshaft_cam_chain_l4','engine--oil_pump_l4'],ignition:['engine--plug_hole_coil_plug_l4','electrical_exhaust_heater_fuel--battery_l4','engine--starter_motor_mitsuba_l4','engine--alternator_denso_l4'],brakes:['chassis--front_brake','chassis--rear_brake','chassis--brake_lines_vsa','chassis--vsa_modulator'],cooling:['engine--water_pump_l4','electrical_exhaust_heater_fuel--radiator_toyo'],fuel:['electrical_exhaust_heater_fuel--fuel_tank','engine--fuel_injector_l4','electrical_exhaust_heater_fuel--air_cleaner'],transmission:['transmission_automatic--at_transmission_case_l4','transmission_automatic--at_solenoid_l4','chassis--driveshaft_half_shaft_l4'],hvac:['body_air_conditioning--a_c_compressor','body_air_conditioning--a_c_condenser','electrical_exhaust_heater_fuel--heater_blower']};
function pickGroups(id){const list=groupsFor(index,id),pick=preferred[id]||[];return [...list].sort((a,b)=>{const x=pick.indexOf(a.id),y=pick.indexOf(b.id);return(x<0?999:x)-(y<0?999:y);});}
function partCard(g,f){const p=f?g.parts.find(p=>p.name.toLowerCase().includes(f.query))||primaryPart(g):primaryPart(g);const art=f?`<button class="card-art atlas" data-group="${g.id}" data-number="${esc(p?.number)}" style="${cropStyle(f)}" aria-label="Explore ${esc(f.title)}"></button>`:`<button class="card-art" data-group="${g.id}" aria-label="Explore ${esc(g.name)}">${imageHTML(p?.images?.[0]||g.diagrams[0]?.image,cleanName(g.name),'loading="lazy" data-image-kind="card"')}</button>`;return `<article class="part-card">${art}<div class="card-copy"><h3>${esc(f?.title||cleanName(g.name))}</h3><p>${esc(f?.desc||(g.parts.length+' catalog entries, including associated seals and hardware.'))}</p><span class="pill">${esc(f?.brand||(modelFor(g)?'3D study + OEM':'Honda OEM'))}</span><button class="button" data-group="${g.id}" data-number="${esc(p?.number)}">Explore assembly <span>→</span></button><div class="card-actions"><button data-group="${g.id}" data-view-hint="diagram" data-number="${esc(p?.number)}">OEM Diagram</button><button data-guides="${g.id}">Guides</button></div>${f?`<a class="card-source" href="${esc(f.website)}" target="_blank" rel="noopener noreferrer">↗ ${esc(new URL(f.website).hostname.replace('www.',''))}</a>`:''}</div></article>`;}
function renderInside(){const g=state.group,s=systemById[state.system];$('assembly-directory').hidden=!s||!!g;$('assembly-filter').value='';
 if(g){$('inside-kicker').textContent='CONNECTED TO THIS ASSEMBLY';$('inside-title').textContent='Context, hardware & service guides';$('inside-count').textContent=modelFor(g)?'3D study + OEM references':'OEM references';const intake=g.id===INTAKE;
 $('inside-content').innerHTML=intake?`<div class="assembly-guide-strip">${icon('engine')}<div><h3>Look underneath the manifold</h3><p>The OEM chart includes the manifold stay (5), harness stay (6), and their associated hardware. Rotate the spatial study underneath, then cross-check the callouts in the diagram.</p></div><button class="button secondary" id="lower-support">Inspect lower support</button></div>`:`<div class="assembly-guide-strip">${icon('book')}<div><h3>${state.detail?'Keep the parent assembly in view':'From the main part to the smallest fastener'}</h3><p>${state.detail?'Return to the assembly to see the component with its neighboring parts.':'Use Hardware to find listed bolts, nuts, screws, and clips. The original numbered diagram remains one click away.'}</p></div><button class="button secondary" data-view="diagram">Show assembly diagram</button></div>`;
 $('inside-content').innerHTML+=`<div class="guide-links"><a href="${esc(g.url)}" target="_blank" rel="noopener noreferrer">OEM catalog ↗</a><a href="${esc(guideFor(g))}" target="_blank" rel="noopener noreferrer">Service information ↗</a><a href="#system/${g.systemId}">Back to ${esc(systemById[g.systemId].name)} →</a></div><div class="related-items"><h3>Neighboring assemblies</h3>${pickGroups(g.systemId).filter(x=>x.id!==g.id).slice(0,3).map(x=>`<button class="directory-item" data-group="${x.id}"><span>${esc(cleanName(x.name))}</span><span>→</span></button>`).join('')}</div>`;return;}
 if(!s){$('inside-kicker').textContent='CHOOSE WHERE TO GO';$('inside-title').textContent='Every system lives in the car';$('inside-count').textContent='Select a system to open its assemblies';$('inside-content').innerHTML='<div class="system-cards">'+SYSTEMS.map(s=>`<button class="system-card" data-system="${s.id}"><span class="count">${groupsFor(index,s.id).length}</span>${icon(s.icon)}<strong>${esc(s.name)}</strong><small>${esc(s.description)}</small></button>`).join('')+'</div>';return;}
 const list=pickGroups(s.id);$('inside-kicker').textContent='INSIDE YOUR ACCORD';$('inside-title').textContent=s.name;$('inside-count').textContent=list.length+' assemblies · select one to go deeper';
 const picks=s.id==='ignition'?featured.filter(f=>['spark-plugs','ignition-coils','battery','battery-cables','starter','starter-relay','alternator'].includes(f.id)):s.id==='brakes'?featured.filter(f=>['front-brakes','rear-brakes','calipers','brake-fluid','brake-hoses','abs-module','parking-brake'].includes(f.id)):s.id==='sensors'?featured.filter(f=>f.sensor):null;
 $('inside-content').innerHTML='<div class="part-cards">'+(picks?picks.filter(f=>index.groupMap.has(f.group)).map(f=>partCard(index.groupMap.get(f.group),f)):list.slice(0,4).map(g=>partCard(g,mainFeature(g)))).join('')+'</div>';renderDirectory('');
}
function renderDirectory(q){if(!state.system)return;const gs=pickGroups(state.system).filter(g=>matches({name:g.name,number:''},q));const missing=index.missing.filter(g=>g.systemId===state.system&&matches({name:g.name},q));$('directory-list').innerHTML=gs.map(g=>`<button class="directory-item" data-group="${g.id}"><span>${esc(cleanName(g.name))}<small>${g.parts.length} entries${modelFor(g)?' · 3D study':''}</small></span><span>→</span></button>`).join('')+missing.map(g=>`<a class="directory-item" href="${esc(g.url)}" target="_blank" rel="noopener noreferrer"><span>${esc(g.name)}<small>Open source catalog</small></span><span>↗</span></a>`).join('')||'<p class="empty-state">No assemblies match that name.</p>';}
function search(q){searchLimit=q===search.lastQuery?searchLimit:24;search.lastQuery=q;const text=q.trim();if(!index){$('search-results').innerHTML='<p class="empty-state">The vehicle catalog is loading.</p>';return;}const systems=SYSTEMS.filter(s=>!text||matches({name:s.name+' '+s.description},text));const gs=index.groups.filter(g=>text?matches({name:g.name},text):[INTAKE,'engine--alternator_denso_l4','chassis--front_brake'].includes(g.id));const ps=text?index.parts.filter(p=>matches(p,text)):[];const button=(g,p)=>`<button class="search-result" data-group="${g.id}" ${p?`data-number="${esc(p.number)}"`:''}><span>${esc(p?p.name:cleanName(g.name))}<small>${p?esc(p.number)+' · ':''}${esc(p?cleanName(g.name):systemById[g.systemId].name)}</small></span><span>→</span></button>`;
 $('search-results').innerHTML=(systems.length?'<p class="search-group">VEHICLE SYSTEMS</p>'+systems.slice(0,8).map(s=>`<button class="search-result" data-system="${s.id}">${icon(s.icon)}<span>${esc(s.name)}<small>${groupsFor(index,s.id).length} assemblies</small></span><span>→</span></button>`).join(''):'')+(gs.length?'<p class="search-group">ASSEMBLIES</p>'+gs.slice(0,searchLimit).map(g=>button(g)).join(''):'')+(ps.length?'<p class="search-group">INDIVIDUAL PARTS · '+fmt(ps.length)+'</p>'+ps.slice(0,searchLimit).map(p=>button(index.groupMap.get(p.groupId),p)).join(''):'')+((gs.length>searchLimit||ps.length>searchLimit)?'<button class="search-result" id="more-search"><span>Show more matches</span><span>↓</span></button>':'');if(!systems.length&&!gs.length&&!ps.length)$('search-results').innerHTML='<p class="empty-state">No matching parts or assemblies. Try a shorter name, a callout, or the OEM part number.</p>';}
function openSearch(){dialog('search-dialog');search($('global-search').value);setTimeout(()=>$('global-search').focus(),20);}
const manualTokens={engine:'Engine, Cooling and Exhaust/Engine/',ignition:'Starting and Charging/',fuel:'Powertrain Management/Fuel Delivery and Air Induction/',cooling:'Engine, Cooling and Exhaust/Cooling System/',transmission:'Transmission and Drivetrain/',brakes:'Brakes and Traction Control/',suspension:'Steering and Suspension/',steering:'Steering and Suspension/',exhaust:'Engine, Cooling and Exhaust/Exhaust System/',electrical:'Power and Ground Distribution/',hvac:'Heating and Air Conditioning/',body:'Body and Frame/',interior:'Body and Frame/',safety:'Restraints and Safety Systems/',sensors:'Sensors and Switches/',accessories:'Accessories and Optional Equipment/'};
function contextualGuides(g,sys){let terms=cleanName(g?.name||'').toLowerCase().replace(/inlet/g,'intake').replace(/\([^)]*\)/g,'').split(/[^a-z]+/).filter(w=>w.length>3&&!['assy','components','front','rear','side'].includes(w));const candidates=manuals.filter(l=>/Service and Repair|Removal|Replacement|Locations|Specifications/.test(l.path));const scored=candidates.map(l=>({l,score:terms.filter(t=>l.path.toLowerCase().includes(t)).length*4+(sys&&l.path.includes(manualTokens[sys])?2:0)})).filter(x=>x.score>=(terms.length?Math.min(8,terms.length*4):2));return scored.sort((a,b)=>b.score-a.score||a.l.path.length-b.l.path.length).slice(0,5).map(x=>x.l);}
function guideFor(g){return contextualGuides(g,g.systemId)[0]?.url||MANUAL;}
function showResources(group){const g=group||state.group,sys=g?.systemId||state.system;const gs=contextualGuides(g,sys);const context=g?cleanName(g.name):systemById[sys]?.name||'your Accord';$('resources-title').textContent='Resources · '+context;$('resource-content').innerHTML=`<p class="dialog-note">Parts, procedures, and manufacturer references for ${esc(context)}.</p>`+(g?`<a class="resource-link" href="${esc(g.url)}" target="_blank" rel="noopener noreferrer">${icon('gear')}<span><strong>${esc(cleanName(g.name))} · OEM catalog</strong><small>Numbered parts, diagrams, and applicable replacements.</small></span><span>↗</span></a>`:'')+gs.map(l=>`<a class="resource-link" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${icon('book')}<span><strong>${esc(l.name)}</strong><small>${esc(l.path.split('/').slice(-3,-1).join(' · '))}</small></span><span>↗</span></a>`).join('')+`<a class="resource-link" href="${MANUAL}" target="_blank" rel="noopener noreferrer">${icon('book')}<span><strong>2012 Accord 2.4L service library</strong><small>Operation CHARM · procedures, locations, wiring, and specifications. Includes equipment variants; select the applicable procedure.</small></span><span>↗</span></a><a class="resource-link" href="https://lemon-manuals.la/" target="_blank" rel="noopener noreferrer">${icon('book')}<span><strong>LEMON manuals</strong><small>Additional service-manual library, linked by Operation CHARM.</small></span><span>↗</span></a>`+brands.filter(([name])=>!['HondaPartsNow','CARB'].includes(name)).map(([name,desc,url])=>`<a class="resource-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer"><span><strong>${esc(name)}</strong><small>${esc(desc)}</small></span><span>↗</span></a>`).join('');dialog('resources-dialog');}
function savePart(){const p=state.part,g=state.group;if(!p||!g)return;const id=g.id+':'+p.number,i=saved.findIndex(s=>s.id===id);if(i>=0){saved.splice(i,1);toast('Removed from saved parts.');}else{saved.push({id,kind:'part',title:p.name,number:p.number,group:g.id,groupName:g.name});toast('Saved to your Accord.');}saveStore();renderPartDetail();}
function renderSaved(){$('plan-items').innerHTML=saved.length?saved.map(item=>`<div class="saved-item"><button class="saved-open" data-saved="${esc(item.id)}">${esc(item.title)}<small>${esc(item.number||'Saved system')} · ${esc(item.groupName||'Vehicle explorer')}</small></button><button class="saved-remove" data-remove-saved="${esc(item.id)}" aria-label="Remove ${esc(item.title)}">Remove</button></div>`).join(''):'<p class="empty-state">Choose a component inside an assembly and save it here for later.</p>';}
function back(){if(state.detail){state.detail=false;state.view=modelFor(state.group)?'3d':'diagram';replaceHash();render();}else if(state.group)chooseSystem(state.group.systemId);else chooseSystem(null);}
async function lowerSupport(){state.detail=false;state.part=state.group.parts.find(p=>p.ref==='5')||state.part;state.filter='all';state.partQuery='';state.view='3d';replaceHash();render();try{const v=await loadViewer();if(state.group?.id!==INTAKE||state.view!=='3d')return;v.preset('below');v.setExplode(.65);$('explode-slider').value=65;v.select('5');toast('Lower support study. Cross-check callouts 5, 6, and the hardware in the OEM diagram.');}catch{show3dFailure();}}
document.addEventListener('click',e=>{
 const a=e.target.closest('[data-close]');if(a){$(a.dataset.close).close();return;}
 const sys=e.target.closest('[data-system]');if(sys){chooseSystem(sys.dataset.system||null);return;}
 const g=e.target.closest('[data-group]');if(g){openGroup(g.dataset.group,g.dataset.number,g.dataset.viewHint);return;}
 const guides=e.target.closest('[data-guides]');if(guides){showResources(index.groupMap.get(guides.dataset.guides));return;}
 const view=e.target.closest('[data-view]');if(view){setView(view.dataset.view);return;}
 const callout=e.target.closest('[data-callout]');if(callout){selectCallout(callout.dataset.callout);return;}
 const row=e.target.closest('[data-row]');if(row){selectRow(Number(row.dataset.row));return;}
 const pf=e.target.closest('[data-part-filter]');if(pf){state.filter=pf.dataset.partFilter;renderInspector();return;}
 const cam=e.target.closest('[data-camera]');if(cam){viewer?.preset(cam.dataset.camera);return;}
 const dz=e.target.closest('[data-diagram-zoom]');if(dz){state.diagramZoom=dz.dataset.diagramZoom==='reset'?1:Math.max(1,Math.min(3,state.diagramZoom+(dz.dataset.diagramZoom==='in'?.5:-.5)));renderDiagram();return;}
 const so=e.target.closest('[data-saved]');if(so){const item=saved.find(s=>s.id===so.dataset.saved);if(item?.group&&index.groupMap.has(item.group))openGroup(item.group,item.number);else{closeDialogs();openSearch();$('global-search').value=item?.title||'';search($('global-search').value);}return;}
 const sr=e.target.closest('[data-remove-saved]');if(sr){saved=saved.filter(s=>s.id!==sr.dataset.removeSaved);saveStore();renderSaved();if(state.group)renderPartDetail();return;}
 if(e.target.closest('.resources-inline')){showResources();return;}
 const id=e.target.closest('[id]')?.id;
 if(id==='inspect-part'){state.detail=true;setView('photo');renderBreadcrumbs();renderInside();}
 else if(id==='save-part')savePart();else if(id==='lower-support')lowerSupport();else if(id==='reset-part-filters'){state.partQuery='';state.filter='all';renderInspector();}else if(id==='more-search'){searchLimit+=24;search($('global-search').value);}else if(id==='retry-catalog')load();
});
$('search-button').addEventListener('click',openSearch);$('global-search').addEventListener('input',e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>search(e.target.value),100);});$('assembly-filter').addEventListener('input',e=>renderDirectory(e.target.value));document.addEventListener('input',e=>{if(e.target.id==='part-filter'){state.partQuery=e.target.value;renderRows();}});document.addEventListener('change',e=>{if(e.target.id==='diagram-select'){state.diagram=Number(e.target.value);state.diagramZoom=1;renderDiagram();}});
$('systems-button').addEventListener('click',()=>{$('workspace').classList.toggle('systems-open');$('system-nav').querySelector('.active')?.focus();if(innerWidth>1000)$('inside-section').scrollIntoView({behavior:'smooth',block:'start'});});$('collapse-systems').addEventListener('click',()=>$('workspace').classList.remove('systems-open'));$('back-button').addEventListener('click',back);$('resources-button').addEventListener('click',()=>showResources());$('footer-resources').addEventListener('click',()=>showResources());$('open-plan').addEventListener('click',()=>{renderSaved();dialog('plan-dialog');});$('explode-slider').addEventListener('input',e=>viewer?.setExplode(Number(e.target.value)/100));$('zoom-in').addEventListener('click',()=>viewer?.zoom(.84));$('zoom-out').addEventListener('click',()=>viewer?.zoom(1.19));$('labels-toggle').addEventListener('click',e=>{const b=e.currentTarget,on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));viewer?.setLabels(on);});$('isolate-toggle').addEventListener('click',e=>{const b=e.currentTarget,on=b.getAttribute('aria-pressed')!=='true';const active=viewer?.isolate(on)||false;b.setAttribute('aria-pressed',String(active));if(on&&!active)toast('This callout is available in the OEM diagram.');});
window.addEventListener('hashchange',route);window.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();openSearch();}if(e.target.closest?.('#stage')&&state.view==='3d'&&viewer){const step=.14,delta=viewer.camera.position.clone().sub(viewer.controls.target);if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const a=(e.key==='ArrowLeft'?-1:1)*step;const x=delta.x*Math.cos(a)-delta.z*Math.sin(a);delta.z=delta.x*Math.sin(a)+delta.z*Math.cos(a);delta.x=x;viewer.camera.position.copy(viewer.controls.target).add(delta);viewer.controls.update();}if(e.key==='+'||e.key==='='){e.preventDefault();viewer.zoom(.85);}if(e.key==='-'){e.preventDefault();viewer.zoom(1.18);}}});
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.style.overflow='';});d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});});
document.addEventListener('error',e=>{const img=e.target;if(!(img instanceof HTMLImageElement))return;const kind=img.dataset.imageKind;if(kind==='diagram'){$('visual-content').innerHTML=`<div class="image-unavailable">This diagram image couldn’t load. The complete parts list is available beside it.<a class="button" href="${esc(state.group.url)}" target="_blank" rel="noopener noreferrer">Open source diagram ↗</a></div>`;$('stage-tools').innerHTML='';}else if(kind==='part'){img.parentElement.innerHTML='<div class="image-unavailable">A separate part photo isn’t available.<button class="button" data-view="diagram">Show component in the diagram</button></div>';}else if(kind==='thumb')img.remove();else if(kind==='card'){const button=img.closest('[data-group]'),g=index?.groupMap.get(button?.dataset.group);if(g?.diagrams[0]?.image&&img.getAttribute('src')!==g.diagrams[0].image){img.src=g.diagrams[0].image;img.dataset.imageKind='card-fallback';}else img.remove();}else if(kind==='card-fallback')img.remove();},true);
document.addEventListener('visibilitychange',()=>viewer?.setActive(!document.hidden&&state.view==='3d'));window.addEventListener('pagehide',()=>viewer?.setActive(false));window.addEventListener('pageshow',()=>viewer?.setActive(state.view==='3d'));
async function load(){try{const r=await fetch('./data/catalog.json');if(!r.ok)throw Error('catalog');rawCatalog=await r.json();let directory=[];try{const d=await fetch('./data/catalog-directory.json');if(d.ok)directory=await d.json();}catch{}index=buildIndex(rawCatalog,directory);$('coverage-line').textContent=fmt(index.parts.length)+' OEM numbers · '+index.groups.length+' assemblies';$('load-state').hidden=true;$('workspace').hidden=false;route();fetch('./data/manuals.json').then(r=>r.ok?r.json():null).then(d=>{manuals=d?.links||[];if(state.group)renderInside();}).catch(()=>{});}catch{$('load-state').innerHTML='Your vehicle catalog couldn’t load. <button class="button" id="retry-catalog">Try again</button>';}}
saveStore();load();
